// ============================================================================
// UEC_apb: APB4 register wrapper around UEC_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/UEC.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/UEC.md
// ============================================================================
module UEC_apb #(
  parameter int MAXP = 16,
  // payload bytes in a packet (power of 2, at most 128)
  parameter int W    = 4,
  // retransmit window, packets (power of 2, 2..8)
  parameter int RXB  = 2,
  // receive buffers (power of 2)
  parameter int RTO  = 256
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic net_tx_valid,
  input logic net_tx_ready,
  output logic [7:0] net_tx_data,
  output logic net_tx_last,
  input logic net_rx_valid,
  input logic [7:0] net_rx_data,
  input logic net_rx_last
);
  localparam logic [31:0] ID_VALUE = 32'h55450200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_enable;
  logic [15:0]   c_start_psn_tx;
  logic [15:0]   c_start_psn_rx;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [7:0]    c_tx_data;
  logic          c_tx_last;
  logic          c_rx_valid;
  logic          c_rx_ready;
  logic [7:0]    c_rx_data;
  logic          c_rx_last;
  logic [2:0]    c_outstanding;
  logic          c_ev_rto;
  logic          c_ev_nack;
  logic          c_ev_dup;
  logic          c_ev_nobuf;
  logic          c_ev_proto;
  UEC_top #(.MAXP(MAXP), .W(W), .RXB(RXB), .RTO(RTO)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .enable(c_enable),
    .start_psn_tx(c_start_psn_tx),
    .start_psn_rx(c_start_psn_rx),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_data(c_tx_data),
    .tx_last(c_tx_last),
    .rx_valid(c_rx_valid),
    .rx_ready(c_rx_ready),
    .rx_data(c_rx_data),
    .rx_last(c_rx_last),
    .net_tx_valid(net_tx_valid),
    .net_tx_ready(net_tx_ready),
    .net_tx_data(net_tx_data),
    .net_tx_last(net_tx_last),
    .net_rx_valid(net_rx_valid),
    .net_rx_data(net_rx_data),
    .net_rx_last(net_rx_last),
    .outstanding(c_outstanding),
    .ev_rto(c_ev_rto),
    .ev_nack(c_ev_nack),
    .ev_dup(c_ev_dup),
    .ev_nobuf(c_ev_nobuf),
    .ev_proto(c_ev_proto)
  );

  // ---------------- registers ----------------
  logic [7:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [0:0] r_CTRL;   // 12'h014 CTRL
  logic [31:0] r_PSN;   // 12'h018 PSN
  logic [8:0] h_TX;   // 12'h01C TX holding register
  logic [8:0] h_RX;   // 12'h020 RX holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 1'h0;
      r_PSN <= 32'h0;
      h_TX <= '0;
      h_RX <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[7:0] & wmask[7:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[6]) r_PSN <= (r_PSN & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7] && !full_TX) h_TX <= (h_TX & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[7] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[8]))) begin
        h_RX[7:0] <= c_rx_data[7:0];
        h_RX[8:8] <= c_rx_last;
        avail_RX <= 1'b1;
      end else if (rd && hit[8]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_enable = r_CTRL;
  assign c_start_psn_tx = r_PSN[15:0];
  assign c_start_psn_rx = r_PSN[31:16];
  assign c_tx_data[7:0] = h_TX[7:0];
  assign c_tx_last = h_TX[8:8];
  assign c_tx_valid = full_TX;
  assign c_rx_ready = ~avail_RX | (rd & hit[8]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_ev_rto;
    irq_set[1] = c_ev_nack;
    irq_set[2] = c_ev_dup;
    irq_set[3] = c_ev_nobuf;
    irq_set[4] = c_ev_proto;
    irq_set[5] = full_TX & c_tx_ready;
    irq_set[6] = wr & (hit[7]) & full_TX;
    irq_set[7] = c_rx_valid & (~avail_RX | (rd & hit[8]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd3: rdata = 32'(flags);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_CTRL);
      10'd6: rdata = 32'(r_PSN);
      10'd7: rdata = 32'(h_TX);
      10'd8: rdata = 32'(h_RX);
      10'd9: rdata = 32'({c_outstanding});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
